def optimize_modelsort(override):
    override('Actors/Actor.cs', [('public Vec3 Position\n\t{', "// Scratch for the world's synchronous render sort; not simulation state.\n    internal float RenderSortDistanceSquared;\n\n    public Vec3 Position\n\t{")])
    override('Scenes/World.cs', [('models.Sort((a, b) =>\n\t\t\t\t(int)((b.Actor.Position - Camera.Position).LengthSquared() -\n\t\t\t\t (a.Actor.Position - Camera.Position).LengthSquared()));', 'SortModels();'), ('private void RenderModels(ref RenderState state, List<ModelEntry> models, ModelFlags flags)', 'private void SortModels()\n    {\n        // Position getters are pure and neither position changes during Sort.\n        // Preserve the original integer-difference comparator and sorting\n        // algorithm, including ties; only reuse its float distance operands.\n        foreach (var entry in models)\n            entry.Actor.RenderSortDistanceSquared = (entry.Actor.Position - Camera.Position).LengthSquared();\n        models.Sort(static (a, b) => (int)(b.Actor.RenderSortDistanceSquared - a.Actor.RenderSortDistanceSquared));\n    }\n\n    private void RenderModels(ref RenderState state, List<ModelEntry> models, ModelFlags flags)')])
